with with_gaps as (select *, case when reading_ts - lag(reading_ts) over (partition by device_code order by reading_ts, id) > interval '30' minute then 1 else 0 end as session_start_flag from device_readings) select id, device_code, reading_ts, temp_c, humidity, pressure, sum(session_start_flag) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as burst_id from with_gaps;
